// The creative engine is a port of cdm v0.2.0 (../creative-decision). tests/fixtures/cdm-cases.json holds random
// problems decided by the Python reference; the port must agree to float noise on every number and every pick.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { Lottery, belief, creativeDecide, expectedMax, fromPoint, pBest, relabel, reversalOrbit, temper, toFactorScore } from "../src/decision-engine/creative.ts";

// Generated by the Python cdm (scripts/cdm-fixtures.py): 40 problems small enough to
// be exact in both, some with custom level utilities, some with no status quo; 6 with 6–8 factors, where both
// compact (cdm at 4096 atoms, the port at 2048), so only the mean is exact and the rest agree to within a grid step.
const { exact, large } = JSON.parse(readFileSync(new URL("./fixtures/cdm-cases.json", import.meta.url), "utf8"));
const close = (a, b, msg, tol = 1e-9) => assert.ok(Math.abs(a - b) <= tol, `${msg}: ${a} vs ${b}`);

describe("creative engine matches the cdm reference", () => {
  exact.forEach((c, n) => it(`exact case ${n}`, () => {
    const d = creativeDecide(c.problem, c.judgments);
    assert.equal(d.commit, c.expect.commit);
    assert.equal(d.innovation, c.expect.innovation);
    assert.deepEqual(d.escalate, c.expect.escalate);
    close(d.evpi, c.expect.evpi, "evpi");
    assert.deepEqual(Object.keys(d.portfolio).sort(), Object.keys(c.expect.portfolio).sort());
    for (const [id, p] of Object.entries(c.expect.portfolio)) close(d.portfolio[id], p, `portfolio ${id}`);
    for (const s of d.stats) {
      const e = c.expect.stats[s.id];
      for (const k of ["mean", "cvar", "pBest", "ei"]) close(s[k], e[k], `${s.id}.${k}`);
      assert.equal(s.status, e.status); assert.equal(s.reliable, e.reliable);
    }
  }));
  large.forEach((c, n) => it(`compacted case ${n}`, () => {
    const d = creativeDecide(c.problem, c.judgments);
    for (const s of d.stats) {
      const e = c.expect.stats[s.id];
      close(s.mean, e.mean, `${s.id}.mean`, 1e-9);
      for (const k of ["cvar", "pBest", "ei"]) close(s[k], e[k], `${s.id}.${k}`, 2e-3);
      assert.equal(s.status, e.status);
    }
    close(d.evpi, c.expect.evpi, "evpi", 2e-3);
    // The commit is an argmax of means, which are exact, so it must agree.
    assert.equal(d.commit, c.expect.commit);
  }));
});

describe("lotteries", () => {
  it("P(best) splits ties fairly and sums to 1", () => {
    const a = Lottery.of([0, 1], [0.5, 0.5]);
    const p = pBest([{ value: a, fail: 0 }, { value: a, fail: 0 }]);
    close(p[0], 0.5, "tie"); close(p[0] + p[1], 1, "sum");
  });
  it("EVPI is never negative", () => {
    const a = Lottery.of([0, 1], [0.5, 0.5]), b = Lottery.point(0.5);
    assert.ok(expectedMax([{ value: a, fail: 0 }, { value: b, fail: 0 }]) >= Math.max(a.mean(), b.mean()));
  });
  it("compaction keeps the mean", () => {
    let v = Lottery.point(0);
    for (let i = 0; i < 8; i++) v = v.add(Lottery.of([0, 0.25, 0.5, 0.75, 1], [0.1, 0.2, 0.3, 0.25, 0.15]).scale(0.1 + i * 0.013));
    assert.ok(v.x.length <= 2048);
    close(v.mean(), [...Array(8).keys()].reduce((a, i) => a + 0.5375 * (0.1 + i * 0.013), 0), "mean");
  });
});

describe("beliefs", () => {
  it("tempering keeps the ranking and 0.5 stays 0.5", () => {
    const p = temper([0.1, 0.6, 0.3], 1.3);
    assert.ok(p[1] > p[2] && p[2] > p[0]);
    close(belief("noul", [[0.5, 0.5]])[1], 0.5, "unknown");
  });
  it("the reversal orbit cancels a direction bias", () => {
    const truth = [0.1, 0.2, 0.4, 0.2, 0.1];
    const [id, rev] = reversalOrbit(5);
    // A judge that always favours the first position it is shown.
    const bias = [1.6, 1.2, 1, 0.9, 0.8];
    const seen = (order) => { const shown = order.map((l, k) => truth[l] * bias[k]); const s = shown.reduce((a, b) => a + b); return relabel(shown.map((x) => x / s), order); };
    const out = belief("score", [seen(id), seen(rev)]);
    assert.ok(Math.abs(out[0] - out[4]) < 1e-9, "symmetric truth comes back symmetric");
  });
  it("factor scores round-trip through a point belief", () => {
    assert.equal(toFactorScore(fromPoint(4, 0.9)).value > 7, true);
    assert.equal(toFactorScore(fromPoint(2, 0.9)).value, 0);
  });
});

describe("speed", () => {
  it("decides 7 options × 8 factors well under a second", () => {
    let seed = 1; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    const dist = () => { const p = [0, 0, 0, 0, 0].map(() => rnd() + 0.05); const s = p.reduce((a, b) => a + b); return p.map((x) => x / s); };
    const problem = { dimensions: [...Array(8).keys()].map((k) => ({ id: `f${k}`, weight: 0.2 + rnd(), levels: 5 })), limits: [{ id: "h", hard: true }, { id: "s", hard: false }] };
    const judgments = [...Array(7).keys()].map((i) => ({ optionId: `o${i}`, baseline: i === 0, dims: Object.fromEntries(problem.dimensions.map((d) => [d.id, dist()])), violations: { h: rnd() * 0.5, s: rnd() }, novelty: dist() }));
    const t = performance.now();
    const d = creativeDecide(problem, judgments);
    assert.ok(performance.now() - t < 1000, "the old product-lottery EI took ~5 s here");
    close(Object.values(d.portfolio).reduce((a, b) => a + b, 0), 1, "portfolio sums to 1");
    close(d.stats.filter((s) => s.status !== "reject").reduce((a, s) => a + s.pBest, 0), 1, "P(best) sums to 1");
  });
});
